mapper.select:
SELECT p.property_id AS propertyId, p.address AS title, p.building_type AS buildingType, p.room_type AS roomType, p.deposit AS deposit, p.monthly_rent AS monthlyRent, p.area AS area, p.floor AS floor, p.address AS address, p.property_latitude AS latitude, p.property_longitude AS longitude, (SELECT image_url FROM property_images pi WHERE pi.property_id = p.property_id ORDER BY display_order ASC LIMIT 1) AS thumbnailUrl, COALESCE(ps.safety_score, 85) AS safetyScore, CASE WHEN COALESCE(ps.safety_score, 85) >= 80 THEN 'SAFE' WHEN COALESCE(ps.safety_score, 85) >= 60 THEN 'WARNING' ELSE 'DANGER' END AS safetyGrade, CASE WHEN b.user_id IS NOT NULL THEN TRUE ELSE FALSE END AS isBookmarked FROM properties p LEFT JOIN property_safety ps ON p.property_id = ps.property_id LEFT JOIN bookmarks b ON p.property_id = b.property_id AND b.user_id = #{userId} WHERE p.del_yn = 'N'
AND p.address LIKE CONCAT('%', #{cond.keyword}, '%')
AND p.building_type = #{cond.buildingType}
AND p.room_type = #{cond.roomType}
AND p.deposit >= #{cond.minDeposit}
AND p.deposit <= #{cond.maxDeposit}
AND p.monthly_rent >= #{cond.minMonthlyRent}
AND p.monthly_rent <= #{cond.maxMonthlyRent}
AND p.property_latitude BETWEEN #{cond.swLat} AND #{cond.neLat} AND p.property_longitude BETWEEN #{cond.swLng} AND #{cond.neLng}
AND (6371 * acos(cos(radians(#{cond.lat})) * cos(radians(p.property_latitude)) * cos(radians(p.property_longitude) - radians(#{cond.lng})) + sin(radians(#{cond.lat})) * sin(radians(p.property_latitude)))) <= #{cond.radius}
ORDER BY p.deposit ASC, p.monthly_rent ASC
ORDER BY p.deposit DESC, p.monthly_rent DESC
ORDER BY COALESCE(ps.safety_score, 0) DESC
ORDER BY p.area DESC
ORDER BY p.property_id DESC
